/* @lc app=leetcode id=4046 lang=kotlin */ class Solution { fun minCost(grid: Array<IntArray>, k: Int): Int = grid.size.let { m -> grid[0].size.let { n -> 1_000_000_000_000_000L.let { INF -> if (m == 1 && n == 1) grid[0][0] else (0..k).fold(Array(m) { i -> LongArray(n) { j -> if (i == 0 && j == 0) grid[0][0].toLong() else INF } }) { e, _ -> Array(m) { LongArray(n) { INF } }.also { nx -> (0 until m).forEach { i -> (1 until n).fold(INF) { run, j -> (minOf(run, e[i][j - 1]) + grid[i][j]).also { nx[i][j] = minOf(nx[i][j], it) } } } }.also { nx -> (0 until m).forEach { i -> (n - 2 downTo 0).fold(INF) { run, j -> (minOf(run, e[i][j + 1]) + grid[i][j]).also { nx[i][j] = minOf(nx[i][j], it) } } } }.also { nx -> (0 until n).forEach { j -> (1 until m).fold(INF) { run, i -> (minOf(run, e[i - 1][j]) + grid[i][j]).also { nx[i][j] = minOf(nx[i][j], it) } } } }.also { nx -> (0 until n).forEach { j -> (m - 2 downTo 0).fold(INF) { run, i -> (minOf(run, e[i + 1][j]) + grid[i][j]).also { nx[i][j] = minOf(nx[i][j], it) } } } } }.let { e -> e[m - 1][n - 1].let { if (it >= INF) -1 else it.toInt() } } } } } }